// An explicit event taxonomy, not natural-language similarity or an AI model.
const ALIASES={greet:'social-contact',near:'social-contact',parallel:'parallel-contact',retreat:'withdraw',back:'withdraw',away:'withdraw',leave:'withdraw',den:'rest',rest:'rest',wait:'wait',watch:'observe',still:'observe',drink:'drink',water:'drink',search:'search',nose:'investigate',sniff:'investigate'};
export const actionMeaning=id=>ALIASES[id]||id;
export function semanticKey(meta){return [meta.cause,meta.goal,meta.conflict,meta.role,[...new Set((meta.actionTypes||meta.actions.map(actionMeaning)))].sort().join(',')].join('|');}
export function stateContext(s,actor){const h=s.humans?.find(h=>h.id===actor),outside=actor.startsWith('water-place:')||actor.startsWith('sleeping-place:');return [s.areaId,actor,outside?s.world:'inside',s.medical?.episode?.kind||s.clinical?.active?.kind||'well',s.stress>=65?'overwhelmed':'settled',outside?'outdoor-space':'familiar-room',Math.floor((s.clinical?.mobility??100)/40),h?.time<30?'limited-time':'usual-time'].join('|');}
export function initSemantics(s){return s.eventSemantics??={version:1,recent:[],learned:{}};}
export function decisionSemantics(s,id,options,explicit=null){
  const social=id==='dog-meet'?s.currentEncounter:null;
  const medical=id==='health-response'?s.medical?.episode?.kind:id==='pain-response'?s.clinical?.active?.kind:null;
  const cause=explicit?.cause|| (medical?'medical-'+medical:social?'animal-'+social.purpose:id.startsWith('journey:')?id.split(':').slice(0,3).join(':'):id);
  return {...{version:1,coverage:explicit?'explicit':'legacy-classification',cause,goal:social?.purpose||id.split(':')[0],conflict:social?.purpose||id.split(':')[0],role:social?'dog':s.caregiverId?'caregiver':'environment',actor:social?.actorId||s.caregiverId||'environment:'+s.areaId,area:s.areaId,actions:options.map(o=>Array.isArray(o)?o[0]:o.id)},...explicit};
}
export function noteDecision(s,meta){const t=initSemantics(s),record={day:s.day,key:semanticKey(meta),goal:meta.goal,conflict:meta.conflict,actor:meta.actor,context:stateContext(s,meta.actor)};t.recent.push(record);t.recent=t.recent.slice(-64);return record;}
export function meaningAllowed(s,meta){const t=initSemantics(s),key=semanticKey(meta),context=stateContext(s,meta.actor);return !t.recent.slice(-3).some(r=>s.day-r.day<=180&&r.context===context&&(r.key===key||r.goal===meta.goal&&r.conflict===meta.conflict));}
export function learnedResponse(s,meta){const r=initSemantics(s).learned[semanticKey(meta)+'|'+meta.actor+'|'+s.areaId];return r&&(r.successes>=2||r.attempts>=3)&&r.context===stateContext(s,meta.actor)&&s.day-r.day<400&&s.stress<65&&meta.actions.includes(r.action)?r.action:null;}
// Familiarity permits autonomous behavior, but one exposure never fixes an action.
// Strong habits still require repeated experience; otherwise current motives decide.
export function familiarSituation(s,meta){const r=initSemantics(s).learned[semanticKey(meta)+'|'+meta.actor+'|'+s.areaId];return !!r&&r.context===stateContext(s,meta.actor)&&s.stress<65;}
export function learnResponse(s,meta,action,positive){const t=initSemantics(s),key=semanticKey(meta)+'|'+meta.actor+'|'+s.areaId,old=t.learned[key];t.learned[key]={day:s.day,action,successes:positive?(old?.action===action?old.successes:0)+1:0,attempts:(old?.attempts||0)+1,context:stateContext(s,meta.actor)};const keys=Object.keys(t.learned);if(keys.length>128)delete t.learned[keys.sort((a,b)=>t.learned[a].day-t.learned[b].day)[0]];}
export function semanticMetrics(log){const rows=log.filter(e=>e.id==='decision'&&e.semantic),window=[],keys=new Set(),actors=new Set(),structures=new Set();let repeated=0,structuresRepeated=0,explicit=0;for(const e of rows){const m=e.semantic,key=semanticKey(m),actions=[...new Set((m.actionTypes||m.actions.map(actionMeaning)))].sort().join(',');if(window.slice(-5).some(r=>r.key===key&&e.day-r.day<=180))repeated++;if(window.slice(-5).some(r=>r.actions===actions&&e.day-r.day<=180))structuresRepeated++;window.push({day:e.day,key,actions});keys.add(key);structures.add(actions);actors.add(m.actor);if(m.coverage==='explicit')explicit++;}return {taggedDecisions:rows.length,explicitDecisions:explicit,semanticTypes:keys.size,actionStructures:structures.size,actors:actors.size,semanticWindowRepeats:repeated,semanticWindowRepeatRatio:rows.length?repeated/rows.length:0,structureWindowRepeatRatio:rows.length?structuresRepeated/rows.length:0,definition:'Same authored cause/goal/conflict/role/canonical actions among previous 5 decisions within 180 days. Actor IDs excluded from type keys; not text embeddings.'};}
export function validateSemantics(s){if(s.pending?.semantic&&!validSemanticMeta(s.pending.semantic))throw Error('손상된 선택 의미');const t=s.eventSemantics;if(!t)return;if(t.version!==1||!Array.isArray(t.recent)||t.recent.length>64||!t.recent.every(r=>Number.isInteger(r.day)&&r.day>=0&&r.day<=s.day&&['key','goal','conflict','actor','context'].every(k=>typeof r[k]==='string'))||!t.learned||typeof t.learned!=='object'||Array.isArray(t.learned)||Object.keys(t.learned).length>128||!Object.values(t.learned).every(r=>Number.isInteger(r.day)&&r.day<=s.day&&r.day>=0&&Number.isInteger(r.successes)&&r.successes>=0&&(r.attempts==null||Number.isInteger(r.attempts)&&r.attempts>=0)&&typeof r.action==='string'&&typeof r.context==='string'))throw Error('손상된 사건 의미 기록');}

export function validSemanticMeta(m){return !!m&&m.version===1&&['explicit','legacy-classification'].includes(m.coverage)&&['cause','goal','conflict','role','actor','area'].every(k=>typeof m[k]==='string'&&m[k].length>0)&&Array.isArray(m.actions)&&m.actions.length>=2&&m.actions.length<=5&&m.actions.every(a=>typeof a==='string')&&new Set(m.actions).size===m.actions.length&&(!m.actionTypes||Array.isArray(m.actionTypes)&&m.actionTypes.length===m.actions.length&&m.actionTypes.every(a=>typeof a==='string'));}
